const roomPanel=document.createElement('section');
roomPanel.id='roomEditor';roomPanel.hidden=true;roomPanel.setAttribute('aria-label','Room furniture editor');document.body.append(roomPanel);
let roomId=null,roomFull=false,roomSelected=null,roomDrag=null;
state.roomLayouts={};
const roomItems=()=>state.roomLayouts[roomId]||[];
const roomZone=()=>state.zones.find(z=>z.id===roomId);
function roomSize(){const z=roomZone();return {w:z.w/PX_PER_METRE*1000,h:z.h/PX_PER_METRE*1000}}
function seedRoom(){const {w,h}=roomSize();return [
 ['Desk','desk',w*.48,h-1950,800,1800],['Sofa','sofa',w*.26,250,2100,850],
 ['Task chair','chair',w*.48-810,h-1310,520,520],['Visitor 1','chair',w*.48+1090,h-1780,520,520],['Visitor 2','chair',w*.48+1090,h-840,520,520],
 ['Cabinet 1','cabinet',120,300,450,1200],['Cabinet 2','cabinet',120,1500,450,1200],['Cabinet 3','cabinet',120,2700,450,1500],
 ['Cabinet 4','cabinet',w-570,1100,450,1400],['Cabinet 5','cabinet',w-570,2500,450,1400]
 ].map((a,i)=>({id:'r'+i,name:a[0],kind:a[1],x:a[2],y:a[3],w:a[4],h:a[5]}))}
function showRoomSetup(id){const z=state.zones.find(z=>z.id===id);if(!z||z.type!=='Office - Teik')return;
 if(roomId===id&&!roomPanel.hidden)roomFull=true;else{roomId=id;roomFull=false;roomSelected=null}
 state.roomLayouts??={};state.roomLayouts[id]??=seedRoom();roomPanel.hidden=false;renderRoom();}
function positionRoom(){if(roomPanel.hidden)return;roomPanel.classList.toggle('expanded',roomFull);if(roomFull){roomPanel.style.cssText='';return}
 const z=roomZone();if(!z){roomPanel.hidden=true;return}const p=svg.createSVGPoint(),m=svg.getScreenCTM();p.x=z.x;p.y=z.y;const a=p.matrixTransform(m);p.x=z.x+z.w;const b=p.matrixTransform(m);
 const width=Math.min(340,Math.max(220,a.x-30)),left=a.x-width-14>=8?a.x-width-14:Math.min(innerWidth-width-8,b.x+14);
 Object.assign(roomPanel.style,{left:left+'px',top:Math.max(85,Math.min(innerHeight-420,a.y-65))+'px',width:width+'px'});}
function doorShape(f){
 const selected=f.id===roomSelected;
 return `<g data-room-item="${f.id}" transform="translate(${f.x} ${f.y})" style="cursor:move"><rect width="${f.w}" height="${f.h}" fill="white" fill-opacity=".85" stroke="${selected?'#53663c':'none'}" stroke-dasharray="35 20" stroke-width="12"/><g transform="rotate(${f.rotation||0} ${f.w/2} ${f.h/2}) translate(${f.flipX?f.w:0} ${f.flipY?f.h:0}) scale(${f.flipX?-1:1} ${f.flipY?-1:1})"><path d="M${f.w} 0V${f.h}M0 0A${f.w} ${f.h} 0 0 0 ${f.w} ${f.h}" stroke="#a18256" stroke-width="18" fill="none"/><circle cx="${f.w}" cy="0" r="24" fill="#a18256"/></g><text x="${f.w/2}" y="${f.h+110}" text-anchor="middle" font-size="85" fill="#655a49" pointer-events="none">DOOR · ${Math.round(f.w)} mm</text></g>`;
}
function roomShapes(){return roomItems().map(f=>{if(f.kind==='door')return doorShape(f);const selected=f.id===roomSelected,color={cabinet:'#dce4e4',sofa:'#d7dfc9',desk:'#d9c9ad',chair:'#ece8de'}[f.kind];return `<g data-room-item="${f.id}" transform="translate(${f.x} ${f.y})" style="cursor:move"><rect width="${f.w}" height="${f.h}" rx="${f.kind==='chair'?110:20}" fill="${color}" stroke="${selected?'#53663c':'#82907b'}" stroke-width="${selected?22:12}"/>${f.kind==='cabinet'?`<path d="M0 0L${f.w} ${f.h}M${f.w} 0L0 ${f.h}" stroke="#91a3a3" stroke-width="8" fill="none"/>`:''}${f.kind==='sofa'?`<rect x="100" y="150" width="${Math.max(50,f.w-200)}" height="${Math.max(50,f.h-200)}" rx="50" fill="none" stroke="#82907b" stroke-width="10"/>`:''}<text transform="translate(${f.w/2} ${f.h/2}) ${f.h>f.w*1.8?'rotate(-90)':''}" text-anchor="middle" dominant-baseline="middle" font-size="85" fill="#495542" pointer-events="none">${esc(f.name)}</text>${selected?[['n',f.w/2,0],['e',f.w,f.h/2],['s',f.w/2,f.h],['w',0,f.h/2]].map(([side,x,y])=>`<circle data-room-side="${side}" cx="${x}" cy="${y}" r="38" fill="white" stroke="#53663c" stroke-width="14" style="cursor:${side==='n'||side==='s'?'ns':'ew'}-resize"/>`).join(''):''}${selected?`<g pointer-events="none" stroke="#56654b" stroke-width="9" fill="none"><path d="M0 ${f.h+70}V${f.h+220}M${f.w} ${f.h+70}V${f.h+220}M0 ${f.h+160}H${f.w}M${f.w+70} 0H${f.w+220}M${f.w+70} ${f.h}H${f.w+220}M${f.w+160} 0V${f.h}"/><text x="${f.w/2}" y="${f.h+140}" text-anchor="middle" fill="#56654b" stroke="white" stroke-width="20" paint-order="stroke" font-size="90">${Math.round(f.w)} mm</text><text transform="translate(${f.w+140} ${f.h/2}) rotate(-90)" text-anchor="middle" fill="#56654b" stroke="white" stroke-width="20" paint-order="stroke" font-size="90">${Math.round(f.h)} mm</text></g>`:''}</g>`}).join('')}
function inspector(){const f=roomItems().find(f=>f.id===roomSelected);return f?`<strong>${esc(f.name)}</strong><div class="room-inputs"><label>X · mm<input type="number" step="100" data-room-field="x" value="${Math.round(f.x)}"/></label><label>Y · mm<input type="number" step="100" data-room-field="y" value="${Math.round(f.y)}"/></label></div><div class="room-inputs"><label>Width · mm<input type="number" min="100" step="100" data-room-field="w" value="${Math.round(f.w)}"/></label><label>Length · mm<input type="number" min="100" step="100" data-room-field="h" value="${Math.round(f.h)}"/></label></div>${f.kind==='cabinet'?'<div class="cab-presets"><span>Module length</span><button data-cab-size="1200">1.2 m</button><button data-cab-size="1400">1.4 m</button><button data-cab-size="1500">1.5 m</button></div>':''}${f.kind==='door'?'<div class="room-actions"><button data-room-action="flipX">Flip left / right</button><button data-room-action="flipY">Flip in / out</button></div>':''}<div class="room-actions"><button data-room-action="rotate">Rotate</button><button data-room-action="delete">Delete item</button></div>`:'<p>Select an item. Drag to move; use the four side points to resize. Dimensions update live.</p>'}
function roomPlanDoorMarkup(z){
 const door=state.doors?.find(d=>d.zoneId===z.id);
 if(!door||typeof doorEdge!=='function')return '';
 const edge=doorEdge(door);if(!edge)return '';
 const scale=1000/PX_PER_METRE,x=(edge.x-z.x)*scale,y=(edge.y-z.y)*scale,width=edge.width*scale;
 return `<g class="room-plan-door" transform="translate(${x} ${y}) rotate(${edge.angle})"><path d="M0 0H${width}" stroke="#fafbf8" stroke-width="55"/><g transform="translate(${door.flipX?width:0} 0) scale(${door.flipX?-1:1} ${door.flipY?-1:1})"><path d="M0 0V${width}M${width} 0A${width} ${width} 0 0 1 0 ${width}" fill="none" stroke="#9a7443" stroke-width="18"/><circle r="25" fill="#9a7443"/></g></g>`;
}
function roomWindowMarkup(w,h){
 const inset=150;
 return `<g class="room-window" pointer-events="none"><line x1="0" y1="${inset}" x2="0" y2="${h-inset}" stroke="#2f91cb" stroke-width="28"/><line x1="38" y1="${inset}" x2="38" y2="${h-inset}" stroke="#63b6df" stroke-width="14"/><line x1="-35" y1="${inset}" x2="75" y2="${inset}" stroke="#2f91cb" stroke-width="18"/><line x1="-35" y1="${h-inset}" x2="75" y2="${h-inset}" stroke="#2f91cb" stroke-width="18"/><text transform="translate(-90 ${h/2}) rotate(-90)" text-anchor="middle" font-size="85" fill="#2f91cb">WINDOW FACADE</text></g>`;
}
function renderRoom(){if(roomPanel.hidden)return;const z=roomZone();if(!z){roomPanel.hidden=true;return}const {w,h}=roomSize();
 roomPanel.innerHTML=`<header class="room-editor-head"><button data-room-action="back" aria-label="Back to full plan">‹ Back to full plan</button><div><small>ROOM SETUP · PLAN ORIENTATION</small><strong>${esc(z.name)}</strong></div><button data-room-action="expand" aria-label="${roomFull?'Reduce room preview':'Expand room preview'}">${roomFull?'↙':'⛶'}</button><button data-room-action="close" aria-label="Close room preview">×</button></header><div class="room-editor-body"><div class="room-editor-drawing"><svg id="roomFurnitureCanvas" viewBox="-250 -250 ${w+600} ${h+650}" aria-label="Editable Teik room furniture" style="touch-action:none"><rect width="${w}" height="${h}" fill="#fafbf8"/><rect width="${w}" height="${h}" stroke="#566454" stroke-width="17.5" fill="none"/>${roomWindowMarkup(w,h)}${roomPlanDoorMarkup(z)}<text x="${w/2}" y="${h*.38}" text-anchor="middle" font-size="220" font-weight="700" fill="#56634f">TEIK OFFICE</text><text x="${w/2}" y="${h*.38+175}" text-anchor="middle" font-size="105" fill="#75806d">${zoneArea(z)} m² NET</text><g id="roomItemsLayer">${roomShapes()}</g></svg></div><aside class="room-editor-tools"><div id="roomInspector">${inspector()}</div><button data-room-action="add" class="room-add">+ Cabinet module</button><button data-room-action="addDoor" class="room-add">+ Door on plan</button><p>${roomFull?'Drag items · 100 mm snap':'Click the zone again or ⛶ to expand'} · Dimensions in mm</p></aside></div>`;positionRoom();}
function refreshRoomFurniture(){roomPanel.querySelector('#roomItemsLayer').innerHTML=roomShapes();roomPanel.querySelector('#roomInspector').innerHTML=inspector()}
function roomPoint(event){const canvas=roomPanel.querySelector('svg'),p=canvas.createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform(canvas.getScreenCTM().inverse())}
function constrainItem(f){const {w,h}=roomSize(),maxW=Math.max(100,Math.floor(w/100)*100),maxH=Math.max(100,Math.floor(h/100)*100);f.w=Math.min(maxW,Math.max(100,Math.round(f.w/100)*100));f.h=Math.min(maxH,Math.max(100,Math.round(f.h/100)*100));const maxX=Math.max(0,Math.floor((w-f.w)/100)*100),maxY=Math.max(0,Math.floor((h-f.h)/100)*100);f.x=Math.min(maxX,Math.max(0,Math.round(f.x/100)*100));f.y=Math.min(maxY,Math.max(0,Math.round(f.y/100)*100))}
roomPanel.addEventListener('pointerdown',event=>{if(event.button!==0)return;const g=event.target.closest('[data-room-item]');if(!g)return;event.preventDefault();event.stopPropagation();roomSelected=g.dataset.roomItem;const f=roomItems().find(f=>f.id===roomSelected);checkpoint();roomDrag={id:f.id,start:roomPoint(event),original:{...f},side:event.target.dataset.roomSide};roomPanel.setPointerCapture(event.pointerId);refreshRoomFurniture()});
roomPanel.addEventListener('pointermove',event=>{if(!roomDrag)return;const p=roomPoint(event),o=roomDrag.original,f=roomItems().find(f=>f.id===roomDrag.id),dx=Math.round((p.x-roomDrag.start.x)/100)*100,dy=Math.round((p.y-roomDrag.start.y)/100)*100;
 if(!roomDrag.side){f.x=o.x+dx;f.y=o.y+dy}else{if(roomDrag.side==='e')f.w=o.w+dx;if(roomDrag.side==='s')f.h=o.h+dy;if(roomDrag.side==='w'){f.x=Math.min(o.x+o.w-100,Math.max(0,o.x+dx));f.w=o.x+o.w-f.x}if(roomDrag.side==='n'){f.y=Math.min(o.y+o.h-100,Math.max(0,o.y+dy));f.h=o.y+o.h-f.y}}constrainItem(f);refreshRoomFurniture()});
function stopRoomDrag(event){roomDrag=null;if(roomPanel.hasPointerCapture(event.pointerId))roomPanel.releasePointerCapture(event.pointerId)}
roomPanel.addEventListener('pointerup',stopRoomDrag);roomPanel.addEventListener('pointercancel',stopRoomDrag);
roomPanel.addEventListener('change',event=>{const field=event.target.dataset.roomField;if(!field)return;const f=roomItems().find(f=>f.id===roomSelected),v=Number(event.target.value);if(!f||!Number.isFinite(v))return;checkpoint();f[field]=v;constrainItem(f);refreshRoomFurniture()});
roomPanel.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const action=b.dataset.roomAction,f=roomItems().find(f=>f.id===roomSelected);if(action==='close'||action==='back'){roomPanel.hidden=true;roomFull=false;setCanvasTool('select');return}if((action==='flipX'||action==='flipY')&&f?.kind==='door'){checkpoint();f[action]=!f[action]}if(action==='addDoor'){startPlanDoor();return}if(action==='expand'){roomFull=!roomFull;renderRoom();return}if(b.dataset.cabSize&&f){checkpoint();f[f.h>=f.w?'h':'w']=+b.dataset.cabSize;constrainItem(f)}if(action==='rotate'&&f){checkpoint();if(f.kind==='door')f.rotation=((f.rotation||0)+90)%360;else [f.w,f.h]=[f.h,f.w];constrainItem(f)}if(action==='delete'&&f){checkpoint();state.roomLayouts[roomId]=roomItems().filter(item=>item.id!==f.id);roomSelected=null}if(action==='add'){checkpoint();const id='cab'+nextId++;roomItems().push({id,name:'Cabinet '+id.slice(3),kind:'cabinet',x:650,y:1400,w:450,h:1200});roomSelected=id;constrainItem(roomItems().at(-1))}refreshRoomFurniture()});
window.addEventListener('resize',positionRoom);new MutationObserver(positionRoom).observe(svg,{attributes:true,attributeFilter:['viewBox']});
document.addEventListener('keydown',event=>{if(!roomPanel.hidden&&event.key==='Escape'){if(roomFull){roomFull=false;renderRoom()}else roomPanel.hidden=true}});
document.addEventListener('keydown',event=>{if(roomPanel.hidden||!roomFull||['INPUT','TEXTAREA'].includes(event.target.tagName))return;if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();event.stopImmediatePropagation();roomPanel.querySelector('[data-room-action="delete"]')?.click()}},true);
